"""Exact solvers used only for testing the reduction."""

from __future__ import annotations

from itertools import product
from typing import Any


def solve_three_sat(instance: dict[str, Any]) -> bool:
    num_vars = instance["num_vars"]
    clauses = instance["clauses"]
    for values in product([False, True], repeat=num_vars):
        assignment = {v: values[v - 1] for v in range(1, num_vars + 1)}
        if all(
            any(assignment[abs(lit)] == (lit > 0) for lit in clause)
            for clause in clauses
        ):
            return True
    return False


def solve_dominating_set(instance: dict[str, Any]) -> bool:
    """Exact branch-and-bound search for a dominating set of size <= k."""
    n = instance["n"]
    k = instance["k"]
    if k < 0:
        return False
    if n == 0:
        return True
    if k >= n:
        return True

    adj = [set() for _ in range(n)]
    for u, v in instance["edges"]:
        adj[u].add(v)
        adj[v].add(u)
    closed = [frozenset(adj[i] | {i}) for i in range(n)]

    failed: set[tuple[frozenset[int], int]] = set()

    def search(undominated: frozenset[int], budget: int) -> bool:
        if not undominated:
            return True
        if budget == 0:
            return False
        key = (undominated, budget)
        if key in failed:
            return False
        # Branch on the undominated vertex with the fewest candidates.
        best = min(
            undominated,
            key=lambda v: sum(1 for u in closed[v] if u in undominated),
        )
        candidates = sorted(closed[best])
        for u in candidates:
            new_und = undominated - closed[u]
            if search(new_und, budget - 1):
                return True
        failed.add(key)
        return False

    return search(frozenset(range(n)), k)
EOF
